async def act(page):
    """
    1) Use the knowledge-base helper create_curated_collection_by_search to find the requested article.
    2) From the helper results, pick the article whose title best matches the long title.
    3) Navigate to that article (use relative goto if URL starts with '/').
    4) Inspect role="img" elements on the article page (alt, title, aria-label, src and any enclosing figcaption)
       for occurrences of variants of 'Shenzhou-20'.
    5) Print exactly 'Yes' if any image appears related, otherwise print exactly 'No'.
    """
    target_url = None

    # 1) Use the search helper (this helper is the required, preferred way to operate the complementary search widget)
    # Utility: create_curated_collection_by_search navigates to '/' and interacts with the accessible search UI,
    # returning structured results (title/url). It's ideal for finding the target article reliably.
    queries = [
        "Beijing extends Mars mission lead; stranded astronauts back home: China’s year in space",
        "Beijing extends Mars mission lead",
        "China's year in space",
        "Beijing extends Mars mission lead China year in space",
        "Shenzhou-20",
    ]

    results = []
    for q in queries:
        try:
            results = await create_curated_collection_by_search(page, q, max_results=50)
        except Exception:
            results = []
        if isinstance(results, list) and len(results) > 0:
            for item in results:
                try:
                    title = (item.get("title") or "").lower()
                except Exception:
                    title = ""
                # Heuristic match to find the long-title article
                if (
                    "beijing extends" in title
                    or ("china" in title and "year in space" in title)
                    or "stranded" in title
                    or "year in space" in title
                ):
                    target_url = item.get("url")
                    break
        if target_url:
            break

    # If helper returned results but none matched heuristics, use first result as fallback
    if not target_url and isinstance(results, list) and len(results) > 0:
        try:
            target_url = results[0].get("url")
        except Exception:
            target_url = None

    # If still no URL, try manual complementary-region search as a last resort (role-centric selectors)
    if not target_url:
        try:
            if await page.get_by_role("complementary").count() > 0:
                comp = page.get_by_role("complementary").nth(0)
                search_input = None
                if await comp.get_by_role("searchbox").count() > 0:
                    search_input = comp.get_by_role("searchbox").nth(0)
                elif await comp.get_by_role("textbox").count() > 0:
                    search_input = comp.get_by_role("textbox").nth(0)

                if search_input is not None:
                    await search_input.fill("Beijing extends Mars mission lead")
                    if await comp.get_by_role("button", name="Search").count() > 0:
                        await comp.get_by_role("button", name="Search").nth(0).click()
                    elif await comp.get_by_role("button").count() > 0:
                        await comp.get_by_role("button").nth(0).click()
                    else:
                        await search_input.press("Enter")

                    try:
                        await page.get_by_role("main").wait_for(timeout=5000)
                    except Exception:
                        try:
                            await page.wait_for_load_state("networkidle", timeout=5000)
                        except Exception:
                            pass

                    if await page.get_by_role("main").count() > 0:
                        main = page.get_by_role("main").nth(0)
                        if await main.get_by_role("article").count() > 0:
                            art_count = await main.get_by_role("article").count()
                            for i in range(art_count):
                                art = main.get_by_role("article").nth(i)
                                title_text = ""
                                url = None
                                if await art.get_by_role("heading").count() > 0:
                                    heading = art.get_by_role("heading").nth(0)
                                    if await heading.get_by_role("link").count() > 0:
                                        link = heading.get_by_role("link").nth(0)
                                        try:
                                            title_text = (await link.inner_text()).strip()
                                        except Exception:
                                            title_text = ""
                                        try:
                                            url = await link.get_attribute("href")
                                        except Exception:
                                            url = None
                                if not title_text and await art.get_by_role("link").count() > 0:
                                    link = art.get_by_role("link").nth(0)
                                    try:
                                        title_text = (await link.inner_text()).strip()
                                    except Exception:
                                        title_text = ""
                                    try:
                                        url = await link.get_attribute("href")
                                    except Exception:
                                        url = None

                                if title_text:
                                    t = title_text.lower()
                                    if (
                                        "beijing extends" in t
                                        or ("china" in t and "year in space" in t)
                                        or "stranded" in t
                                    ):
                                        target_url = url
                                        break
        except Exception:
            target_url = target_url

    # If still not found, cannot proceed
    if not target_url:
        print("No")
        return

    # 2) Navigate to the article page (prefer relative goto when possible)
    try:
        if isinstance(target_url, str) and target_url.startswith("/"):
            await page.goto(target_url)
        else:
            await page.goto(target_url)
    except Exception:
        print("No")
        return

    # 3) Inspect accessible images for 'Shenzhou-20' variants
    img_locator = page.get_by_role("img")
    try:
        img_count = await img_locator.count()
    except Exception:
        img_count = 0

    term_variants = ["shenzhou-20", "shenzhou 20", "shenzhou20", "shenzhou"]
    found = False

    for i in range(img_count):
        img = img_locator.nth(i)
        try:
            alt = (await img.get_attribute("alt")) or ""
        except Exception:
            alt = ""
        try:
            title_attr = (await img.get_attribute("title")) or ""
        except Exception:
            title_attr = ""
        try:
            aria = (await img.get_attribute("aria-label")) or ""
        except Exception:
            aria = ""
        try:
            src = (await img.get_attribute("src")) or ""
        except Exception:
            src = ""
        caption = ""
        try:
            caption = await img.evaluate(
                "el => { const fig = el.closest('figure'); if(!fig) return ''; const cap = fig.querySelector('figcaption'); return cap ? cap.innerText : ''; }"
            ) or ""
        except Exception:
            caption = ""

        combined = " ".join([alt, title_attr, aria, src, caption]).lower()
        for term in term_variants:
            if term in combined:
                found = True
                break
        if found:
            break

    print("Yes" if found else "No")

